#define DT_DRV_COMPAT zephyr_i2c_emul_controller

#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/sys/util.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(i2c_emul, CONFIG_I2C_LOG_LEVEL);

struct i2c_emul_data {
	struct k_mutex mutex;
	const struct i2c_emul *emul_list;
	size_t emul_list_len;
};

struct i2c_emul_config {
	uint32_t bus_speed;
};

static int i2c_emul_transfer(const struct device *dev, struct i2c_msg *msgs,
			     uint8_t num_msgs, uint16_t slave_address)
{
	struct i2c_emul_data *data = dev->data;
	int rc;

	k_mutex_lock(&data->mutex, K_FOREVER);

	for (size_t i = 0; i < data->emul_list_len; i++) {
		if (data->emul_list[i].addr == slave_address) {
			rc = data->emul_list[i].api->transfer(
				data->emul_list[i].target, msgs, num_msgs,
				slave_address);
			k_mutex_unlock(&data->mutex);
			return rc;
		}
	}

	LOG_ERR("No emulator for slave address 0x%02x", slave_address);
	k_mutex_unlock(&data->mutex);
	return -ENODEV;
}

static int i2c_emul_get_config(const struct device *dev, uint32_t *config)
{
	const struct i2c_emul_config *cfg = dev->config;

	*config = I2C_MODE_MASTER | I2C_SPEED_SET(cfg->bus_speed);
	return 0;
}

static int i2c_emul_configure(const struct device *dev, uint32_t dev_config)
{
	const struct i2c_emul_config *cfg = dev->config;
	uint32_t speed = I2C_SPEED_GET(dev_config);

	if ((dev_config & I2C_MODE_MASTER) == 0U) {
		return -EINVAL;
	}

	if (speed != I2C_SPEED_GET(cfg->bus_speed)) {
		return -EINVAL;
	}

	return 0;
}

static const struct i2c_driver_api i2c_emul_api = {
	.configure = i2c_emul_configure,
	.transfer = i2c_emul_transfer,
	.get_config = i2c_emul_get_config,
};

static int i2c_emul_init(const struct device *dev)
{
	struct i2c_emul_data *data = dev->data;

	k_mutex_init(&data->mutex);
	return 0;
}

/*
 * Device tree definitions for I2C emulator controllers.
 *
 * Each instance of 'zephyr,i2c-emul-controller' in the device tree
 * defines an I2C bus that can host emulated I2C devices.
 */

#define Z_I2C_EMUL_LIST_INIT(inst) \
	{ \
		DT_INST_FOREACH_CHILD_STATUS_OKAY(inst, Z_I2C_EMUL_ITEM_INIT) \
	}

#define Z_I2C_EMUL_ITEM_INIT(node_id) \
	{ \
		.addr = DT_REG_ADDR(node_id), \
		.api = (const struct i2c_emul_api *) \
			DT_PROP(node_id, i2c_emul_api), \
		.target = (void *)DT_PROP(node_id, i2c_emul_target), \
	},

#define I2C_EMUL_CONTROLLER_DEFINE(inst) \
	static const struct i2c_emul i2c_emul_list_##inst[] = \
		Z_I2C_EMUL_LIST_INIT(inst); \
	\
	static struct i2c_emul_data i2c_emul_data_##inst = { \
		.emul_list = i2c_emul_list_##inst, \
		.emul_list_len = ARRAY_SIZE(i2c_emul_list_##inst), \
	}; \
	\
	static const struct i2c_emul_config i2c_emul_config_##inst = { \
		.bus_speed = DT_INST_PROP(inst, clock_frequency), \
	}; \
	\
	DEVICE_DT_DEFINE(DT_INST(inst, DT_DRV_COMPAT), \
			    i2c_emul_init, \
			    NULL, \
			    &i2c_emul_data_##inst, \
			    &i2c_emul_config_##inst, \
			    POST_KERNEL, CONFIG_I2C_INIT_PRIORITY, \
			    &i2c_emul_api);

DT_INST_FOREACH_STATUS_OKAY(DT_DRV_COMPAT, I2C_EMUL_CONTROLLER_DEFINE)
